yLimit = len(map)
xLimit = len(map[0])
splitterValueDictionary = {}
debug = False
freezeTime = False

for yCoordinate , row in enumerate(map):
    for xCoordinate , space in enumerate(row):
        if space == "^":
            splitterValueDictionary[str(yCoordinate) + "+" + str(xCoordinate)] = [0,0] #create a dictionary for each splitter corrdinate
#the purpose of the dictionary is to create a reference point for the program to determine if the splitters possible biways have been fully
#enumerated. Each coordinate for a splitter is the key in the dictionary, and the corresponding value to that key is a list. This
#list will hold two integers, a left and a right. This list represents the combined value of the left and the right paths and 
#acts as a place holder for the values of the splitters. If the right value of a path is discovered, index 1 in the corresponding
#list will have a value other than zero. The way to determine if a splitter has not been fully checked is to find out if
#the left or the right values in the list are 0. If so, that splitter is not yet fully evaluated. 


def splitterValueFinder(y , x , direction): #this function determines if a splitters value will be the sum of its lower splitters, or, if it has no lower splitters, will set that coordinates splitter path value to 1.    
    dy = 1 #create a temp value dy which represents the change in y, used to find the nearest splitter value in the dictionary
    while y + dy < yLimit and map[y + dy][x] == ".": #check down two if there is a splitter that this beam of light came from. Continue searching only if the coordinate that is being tested is not founded in the dictionary and the search has not delved below the map
        if debug: print("Checking downward for a splitter or the bottom of the map. \ndy's value is: " , dy)
        if freezeTime: input()
        dy += 1 #if the splitter has not been found, search below by one by incrementing dy

    #at this point the while loop will have been exited. Either it will have exited because the bottom of the map was hit, or a coordinate for a splitter has been found. The following code will determine which.
    
    if y + dy >= yLimit: #fell off the map in search of a lower splitter. Therefore this splitter takes a direct path to the bottem of the map. Set its pathway value equal to 1 for the 1 unique pathway it represents.
        if debug: print("Found the bottom of the map")
        if freezeTime: input()
        if direction == "Right of the splitter":
            if debug: print("Discovered splitters right path value: " , 1)
            if freezeTime: input()
            splitterValueDictionary[str(y) + "+" + str(x - 1)][1] = 1 #set the right path value
        else:
            if debug: print("Discovered splitters left path value: " , 1)
            if freezeTime: input()
            splitterValueDictionary[str(y) + "+" + str(x + 1)][0] = 1 #set the left path value
    else: #if the code found a splitter coordinate and that is why it broke from the while loop.
        if debug: print("Found origin splitter")
        if freezeTime: input()
        if direction == "Right of the splitter": #if the y , x coordinate that the beam of light is on is to the right of the splitter, then adjust the right value of the splitter
            splitterValueDictionary[str(y) + "+" + str(x - 1)][1] = splitterValueDictionary.get(str(y + dy) + "+" + str(x))[0] + splitterValueDictionary.get(str(y + dy) + "+" + str(x))[1] #The right path is now equal to the sum of the right and left paths of its lower splitters
            if debug: print("Discovered splitters right path value: " , splitterValueDictionary[str(y) + "+" + str(x - 1)][1])
            if freezeTime: input()
        else: #else adjust the left pathway value of this splitter
            splitterValueDictionary[str(y) + "+" + str(x + 1)][0] = splitterValueDictionary.get(str(y + dy) + "+" + str(x))[0] + splitterValueDictionary.get(str(y + dy) + "+" + str(x))[1] #The right path is now equal to the sum of the right and left paths of its lower splitters
            if debug: print("Discovered splitters left path value: " , splitterValueDictionary[str(y) + "+" + str(x + 1)][0])
            if freezeTime: input()

def nextCoordinateToSearch(y , x): #this function determines where to call reverseQuantumTachyon next to continue the function
    #most of this code is identical to code from the splitterValueFinder
    dy = 1 #create a temp value dy which represents the change in y, used to find the nearest splitter value in the dictionary
    while y + dy < yLimit and map[y + dy][x] == ".": #check down two if there is a splitter that this beam of light came from, keep searching until the bottom is hit or a splitter is found 
        dy += 1 #if the splitter has not been found, search below by one by incrementing dy

    if y + dy >= yLimit: #the beam of light did not originiate from a splitter, therefore it originated from the bottom of the map. Continue exploring the bottom of the map moving to the right.
        if y + 1 == yLimit - 1 and x == xLimit - 1: #if the beam originated from the bottom of the map, however, the beam is at the final edge of this map, then begin the next search and the leftmost upper splitter.
            reverseQuantumTachyon(yLimit - 2 , 1)
        else:
            reverseQuantumTachyon(yLimit - 1 , x + 1)
    
    else:#the beam of light originated from a splitter, therefore the next place to search is the next rightmost beam of light in that same row, or the upper collums first splitter if this is the last splitter searched on this row
        dx = 2
        while x + dx < xLimit and map[y + dy][x + dx] == ".":
            dx += 1
        if map[y + dy][x + dx] == "^": #if another splitter in the current row is found, start the search from that splitter now
            reverseQuantumTachyon(y + dy , x + dx)
        else: #fell off the right side of the map, therefore all splitters in this row have been mapped out and evaluated, now move on to the upper rows to start from
            x = 2 #setting it to two hard codes the dx to the input, however, I know I can skip over a few iterations by doing this and still prep for the worst case
            while map[y + dy - 2][x] != "^": #move up two rows, and begin the search for the next splitter to start on at element 3 in the row
                x += 1 #increment x to keep searching
            #found the next starting splitter
            reverseQuantumTachyon(y + dy - 2 , x)


def reverseQuantumTachyon(y , x):
    if y == 2 and x == 70: #hard coded the top's coordinates, this is not the S, but the top most ^
        if debug: print("Hit the top!")
        if freezeTime: input()
        return #if you finally got to the top of the quantum tachyon, return (technically redundant but as a stoping point it is relevant)
    
    elif x + 1 < xLimit and map[y][x + 1] == "^": #check if there is a splitter to the right first
        if map[y][x - 1] == "^": #check if there is a splitter to the left next
            if debug: print("Found splitter on my right --> and my left <--")
            if freezeTime: input()
            splitterValueFinder(y , x , "Left of the splitter") #first determine the value of the splitter on the right, the direction left refers to the beam of light in relation to the splitter. In this case, the beam of light is on the left side of the splitter.
            splitterValueFinder(y , x , "Right of the splitter") #do the same for the left splitter
            nextCoordinateToSearch(y , x)

        else:
            if debug: print("Found splitter on my right -->")
            if freezeTime: input()
            splitterValueFinder(y , x , "Left of the splitter") #splitter is on the right, determine the value of its left path
            nextCoordinateToSearch(y , x)

    elif map[y][x - 1] == "^": #check if there is a splitter to the left
        if debug: print("Found splitter on my left <--")
        if freezeTime: input()
        splitterValueFinder(y , x , "Right of the splitter") #first determine the value of the splitter on the left, the direction right refers to the beam of light in relation to the splitter. In this case, the beam of light is on the right side of the splitter.
        nextCoordinateToSearch(y , x)

    elif map[y - 1][x] == ".": #if empty space then move into it
        if debug: print("Found empty space above me, moving up") 
        if freezeTime: input()
        reverseQuantumTachyon(y - 1 , x) #move up

    elif map[y - 1][x] == "^": #if there is a splitter directly above, then begin the splitter search one to the right instead. The only time this will happen is if we started from the bottom of the map and we are searching every coordinate, as I have scrubbed the map of unused splitters.
        if debug: print("Found splitter above me, restarting search and moving right")
        if freezeTime: input()
        reverseQuantumTachyon(yLimit - 1 , x + 1)

#try:
reverseQuantumTachyon(yLimit - 1 , 0)
